import zipfile
from xml.etree import ElementTree as ET

M = 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'
NS = {'m': M}

with zipfile.ZipFile('budget.xlsx') as z:
    root = ET.fromstring(z.read('xl/worksheets/sheet1.xml'))

expenses = []  # (row, category, item, amount)
for row in root.findall('.//m:row', NS):
    cells = {}
    for c in row.findall('m:c', NS):
        ref = c.get('r')
        v = c.find('m:v', NS)
        cells[ref[0]] = (ref, v.text if v is not None else None)
    if 'C' in cells and 'A' in cells and cells['C'][1] is not None:
        try:
            amt = float(cells['C'][1])
        except (TypeError, ValueError):
            continue
        r = int(cells['C'][0][1:])
        if 11 <= r <= 22:
            expenses.append((r, cells['A'][1], cells['B'][1], amt))

total = sum(e[3] for e in expenses)
print(f"Expense rows parsed: {len(expenses)}")
for r, cat, item, amt in expenses:
    print(f"  {r:>2}  {cat:<15} {item:<16} {amt:>8.2f}")
print(f"TOTAL EXPENSES: {total:.2f}")

# Per-category subtotals
cats = {}
for r, cat, item, amt in expenses:
    cats[cat] = cats.get(cat, 0.0) + amt
print("\nPer-category subtotals:")
for cat, s in cats.items():
    print(f"  {cat:<15} {s:>8.2f}")

# Cross-check with the workbook's own formula
for row in root.findall('.//m:row', NS):
    for c in row.findall('m:c', NS):
        if c.get('r') == 'C23':
            f = c.find('m:f', NS)
            print(f"\nWorkbook formula in C23: ={f.text if f is not None else '?'}")

